sessions = [  # Fiddler 에서 내보낸 세션 요약(가상)
    {"host": "outlook.office365.com", "status": 200, "ms": 180, "cert": "DigiCert"},
    {"host": "login.microsoftonline.com", "status": 407, "ms": 30, "cert": None},
    {"host": "teams.microsoft.com", "status": 200, "ms": 2400, "cert": "CorpProxy-CA"},
    {"host": "contoso.sharepoint.com", "status": 200, "ms": 210, "cert": "DigiCert"},
    {"host": "autodiscover.contoso.com", "status": 404, "ms": 95, "cert": "DigiCert"},
]
for s in sessions:
    why = []
    if s["status"] == 407:
        why.append("프록시가 인증을 요구 — M365 주소는 프록시 인증을 빼야 한다")
    if s["cert"] and s["cert"] not in ("DigiCert", "Microsoft"):
        why.append(f'인증서 발급자 {s["cert"]} — 중간에서 TLS 를 풀어 보고 있다')
    if s["ms"] > 1000:
        why.append(f'{s["ms"]}ms 로 느림')
    if s["status"] == 404 and s["host"].startswith("autodiscover"):
        why.append("자동 검색 주소가 없음 — DNS·하이브리드 설정 확인")
    if why:
        print(f'{s["host"]:<26} {s["status"]}  ' + " / ".join(why))

# login.microsoftonline.com  407  프록시가 인증을 요구 — M365 주소는 프록시 인증을 빼야 한다
# teams.microsoft.com        200  인증서 발급자 CorpProxy-CA — 중간에서 TLS 를 풀어 보고 있다 / 2400ms 로 느림
# autodiscover.contoso.com   404  자동 검색 주소가 없음 — DNS·하이브리드 설정 확인
